<?php
require __DIR__.'/auth.php';require __DIR__.'/../event-common.php';
$eid=filter_input(INPUT_GET,'event_id',FILTER_VALIDATE_INT) ?: filter_var($_POST['event_id']??null,FILTER_VALIDATE_INT);
if(!$eid){http_response_code(400);exit('Invalid exhibition');}
$s=$conn->prepare('SELECT title FROM events WHERE event_id=?');$s->bind_param('i',$eid);$s->execute();$event=$s->get_result()->fetch_assoc();$s->close();if(!$event){http_response_code(404);exit('Exhibition not found');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!eventValidToken()){http_response_code(403);exit('Invalid form token');}
 $selected=array_unique(array_map('intval',$_POST['artworks']??[]));$selected=array_values(array_filter($selected,fn($n)=>$n>0));
 try{$conn->begin_transaction();$del=$conn->prepare('DELETE FROM event_artworks WHERE event_id=?');$del->bind_param('i',$eid);$del->execute();$del->close();$check=$conn->prepare("SELECT artwork_id FROM artworks WHERE artwork_id=? AND LOWER(status)='approved'");$insert=$conn->prepare('INSERT INTO event_artworks(event_id,artwork_id) VALUES (?,?)');foreach($selected as $aid){$check->bind_param('i',$aid);$check->execute();if(!$check->get_result()->num_rows)continue;$insert->bind_param('ii',$eid,$aid);$insert->execute();}$check->close();$insert->close();$conn->commit();eventGo('event-artworks.php?event_id='.$eid.'&saved=1');}catch(Throwable $e){$conn->rollback();error_log($e->getMessage());http_response_code(500);exit('Unable to save exhibition artworks');}
}
$s=$conn->prepare("SELECT a.artwork_id,a.title,u.FULL_NAME AS artist_name,EXISTS(SELECT 1 FROM event_artworks ea WHERE ea.event_id=? AND ea.artwork_id=a.artwork_id) AS selected FROM artworks a JOIN users u ON u.USER_ID=a.user_id WHERE LOWER(a.status)='approved' ORDER BY a.created_at DESC");$s->bind_param('i',$eid);$s->execute();$artworks=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Exhibition Artworks | MIRA</title><script>try{document.documentElement.dataset.theme=localStorage.getItem('mira-theme')||'light'}catch(e){}</script><link rel="stylesheet" href="../event.css"></head><body class="event-page"><main class="event-container"><a href="events.php">← All exhibitions</a><h1>Select artworks for <?=eventEsc($event['title'])?></h1><?php if(isset($_GET['saved'])):?><p class="event-alert">Artworks updated successfully.</p><?php endif;?><form method="post" class="event-card event-form"><input type="hidden" name="csrf" value="<?=eventEsc(eventToken())?>"><input type="hidden" name="event_id" value="<?=$eid?>"><p>Select approved artworks to include in this exhibition.</p><?php foreach($artworks as $a):?><label class="event-checkbox"><input type="checkbox" name="artworks[]" value="<?= (int)$a['artwork_id'] ?>" <?=$a['selected']?'checked':''?>><?=eventEsc($a['title'])?> — <?=eventEsc($a['artist_name'])?></label><?php endforeach;?><?php if(!$artworks):?><p>No approved artworks available yet.</p><?php endif;?><button class="event-primary" type="submit">Save selection</button></form></main></body></html>
